  const inputs = [Object.freeze([])];
  let level = inputs;
  for (let length = 1; length <= 4; length++) {
    level = level.flatMap(a => ['', 'x', 'y'].map(line => Object.freeze([...a, line])));
    inputs.push(...level);
  }
  for (const a of inputs) for (const b of inputs) verifyPair(a, b);
});

test('prefix preservation and context merging boundaries', () => {
  for (const gap of [0, 1, 2, 3, 4, 5, 6, 7]) {
    const a = Object.freeze(['-old', ...Array.from({ length: gap }, (_, i) => ` ${i}`), '+old', '']);
    const b = Object.freeze(['+new', ...a.slice(1, -2), '-new', '']);
    verifyPair(a, b);
  }
  assert.deepEqual(unifiedHunks(['a'], ['a']), []);
  assert.deepEqual(unifiedHunks([], ['+x'], { context: 0 }), [
    { oldStart: 0, oldLines: 0, newStart: 1, newLines: 1, lines: ['++x'] },
  ]);
  assert.deepEqual(unifiedHunks(['-x'], [], { context: 0 }), [
    { oldStart: 1, oldLines: 1, newStart: 0, newLines: 0, lines: ['--x'] },
  ]);
  assert.deepEqual(unifiedHunks(['a', 'b'], ['a', 'b', 'c'], { context: 0 }), [
    { oldStart: 2, oldLines: 0, newStart: 3, newLines: 1, lines: ['+c'] },
  ]);
});

test('application rejects malformed, mismatched, overlapping and out-of-order hunks', () => {
  const a = Object.freeze(['a', 'b', 'c', 'd']);
  const valid = { oldStart: 2, oldLines: 1, newStart: 2, newLines: 1, lines: ['-b', '+B'] };
  const invalid = [
    null, {}, { ...valid, lines: null }, { ...valid, lines: [42] },
    { ...valid, lines: [''] }, { ...valid, lines: ['?b'] },
    { ...valid, lines: ['-wrong', '+B'] }, { ...valid, lines: [' wrong'] },
    { ...valid, oldStart: 0 }, { ...valid, oldStart: -1 },
    { ...valid, oldStart: 1.5 }, { ...valid, oldStart: '2' },
    { ...valid, oldStart: Infinity }, { ...valid, oldStart: 6 },
    { ...valid, oldLines: -1 }, { ...valid, oldLines: 0 },
    { ...valid, oldLines: 2 }, { ...valid, oldLines: 10 },
    { ...valid, newStart: 0 }, { ...valid, newStart: 3 },
    { ...valid, newLines: 0 }, { ...valid, newLines: 2 },
    { ...valid, newLines: NaN }, { ...valid, newLines: Number.MAX_SAFE_INTEGER + 1 },
  ];
  for (const hunk of invalid) assert.throws(() => applyHunks(a, [hunk]), /hunk 0 does not apply/);
  assert.throws(() => applyHunks(a, [valid, valid]), /hunk 1 does not apply/);
  const later = { oldStart: 4, oldLines: 1, newStart: 4, newLines: 1, lines: ['-d', '+D'] };
  assert.throws(() => applyHunks(a, [later, valid]), /hunk 1 does not apply/);
  assert.throws(() => applyHunks(a, [valid, null]), /hunk 1 does not apply/);
  assert.deepEqual(applyHunks(a, [valid, later]), ['a', 'B', 'c', 'D']);
  assert.deepEqual(applyHunks(a, [
    { oldStart: 1, oldLines: 0, newStart: 2, newLines: 1, lines: ['+x'] },
    { oldStart: 1, oldLines: 0, newStart: 3, newLines: 1, lines: ['+y'] },
  ]), ['a', 'x', 'y', 'b', 'c', 'd']);
});

test('small changes in 20,000-line files stay well below one second', () => {
  for (const repetitive of [false, true]) {
    const a = Object.freeze(Array.from({ length: 20000 }, (_, i) => repetitive ? 'repeat' : `line ${i}`));
    const b = a.slice();
    b.splice(19000, 1);
    b.splice(10000, 1, 'replacement');
    b.splice(100, 0, 'insertion');
    Object.freeze(b);
    const start = performance.now();
    const hunks = unifiedHunks(a, b);
    const patched = applyHunks(a, hunks);
    const milliseconds = performance.now() - start;
    assert.deepEqual(patched, b);
    assert.ok(milliseconds < 500, `${milliseconds} ms`);
    console.log(`20,000 lines (${repetitive ? 'repetitive' : 'unique'}): ${milliseconds.toFixed(1)} ms`);
  }
});
